async def act(page):
    """
    Attempt to find the post "I Ditched VS Code For The Open-Source VSCodium, And I Have No Regrets"
    and leave the comment "This gives me a new angle to consider.".

    Strategy:
    1. Use the site-aware helper monitor_keyword_and_notify to scan the homepage for the exact title
       (this helper is appropriate because it navigates to '/' and extracts article links using
       accessibility-role-centric selectors). If it finds the post, navigate to its URL and proceed
       to post the comment.
    2. If the helper returns no matches, retry with a shorter keyword "VSCodium".
    3. If still no matches, navigate to the Sample Page (relative goto to "/?page_id=2") and search
       all visible links there for the target title or partial keywords (case-insensitive). If a link
       is located, navigate to it and attempt to post the comment.
    4. On the post page, locate a comment textbox (prefer textboxes inside a role="form"), fill it
       with the requested comment, and click a submit button (prefer a button inside the same form).

    Notes about knowledge-base helpers considered:
    - monitor_keyword_and_notify: appropriate for scanning the homepage for article titles and URLs.
      It is used first because it encapsulates robust accessibility-role-based scanning. If it fails to
      find articles (as seen in prior runs), the code falls back to manually searching visible links on
      a likely content page (Sample Page).
    - Other helpers (create_curated_collection_by_search, etc.) always navigate to '/' and expect a
      visible search widget; the current accessibility tree doesn't expose such a widget, so they are
      not used here.
    """

    TARGET_TITLE = "I Ditched VS Code For The Open-Source VSCodium, And I Have No Regrets"
    COMMENT_TEXT = "This gives me a new angle to consider."

    # 1) Try the knowledge-base helper that scans the homepage
    try:
        matches = await monitor_keyword_and_notify(page, TARGET_TITLE, check_interval_minutes=60, notify_via="structured", max_results=10)
    except Exception:
        matches = []

    # 2) Fallback to shorter keyword if needed
    if not matches:
        try:
            matches = await monitor_keyword_and_notify(page, "VSCodium", check_interval_minutes=60, notify_via="structured", max_results=10)
        except Exception:
            matches = []

    post_href = None
    if matches:
        # take the first returned match's url if present
        first = matches[0]
        post_href = first.get("url") if isinstance(first, dict) else None

    # 3) If helper didn't find anything, navigate to the Sample Page and search links there
    if not post_href:
        # Use relative goto for the known Sample Page link
        try:
            await page.goto("/?page_id=2")
        except Exception:
            # If goto fails for some reason, continue and try to use available link on current page
            pass

        # wait for main or networkidle
        main = page.get_by_role("main")
        if await main.count() > 0:
            try:
                await main.nth(0).wait_for(timeout=4000)
            except Exception:
                pass
        else:
            try:
                await page.wait_for_load_state("networkidle")
            except Exception:
                pass

        # Try exact match first
        exact_links = page.get_by_role("link", name=TARGET_TITLE)
        if await exact_links.count() > 0:
            post_href = await exact_links.nth(0).get_attribute("href")

        # Fallback: partial keywords
        if not post_href:
            for partial in ["VSCodium", "VS Code"]:
                partial_links = page.get_by_role("link", name=partial)
                if await partial_links.count() > 0:
                    post_href = await partial_links.nth(0).get_attribute("href")
                    if post_href:
                        break

        # Last resort: iterate all links and inspect visible text
        if not post_href:
            all_links = page.get_by_role("link")
            total = await all_links.count()
            for i in range(total):
                link = all_links.nth(i)
                try:
                    text = (await link.inner_text()) or ""
                except Exception:
                    text = ""
                t = text.strip()
                if not t:
                    continue
                low = t.lower()
                if TARGET_TITLE.lower() in low or "vscodium" in low or "vs code" in low:
                    post_href = await link.get_attribute("href")
                    if post_href:
                        break

    if not post_href:
        print("Could not find the requested post on the site.")
        return

    # 4) Navigate to the post page (relative goto allowed). This navigation is expected.
    await page.goto(post_href)

    # After navigation, wait for main region or for networkidle
    main = page.get_by_role("main")
    if await main.count() > 0:
        try:
            await main.nth(0).wait_for(timeout=5000)
        except Exception:
            pass
    else:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            pass

    # 5) Locate comment textbox, prefer one inside a form (use full get_by_role path)
    comment_box = None
    form_locator = page.get_by_role("form")
    if await form_locator.count() > 0:
        form = form_locator.nth(0)
        labelled = form.get_by_role("textbox", name="Comment")
        if await labelled.count() > 0:
            comment_box = labelled.nth(0)
        else:
            any_textbox = form.get_by_role("textbox")
            if await any_textbox.count() > 0:
                comment_box = any_textbox.nth(0)

    # Page-level fallbacks
    if comment_box is None:
        labelled_page = page.get_by_role("textbox", name="Comment")
        if await labelled_page.count() > 0:
            comment_box = labelled_page.nth(0)
        else:
            any_page_textbox = page.get_by_role("textbox")
            if await any_page_textbox.count() > 0:
                comment_box = any_page_textbox.nth(0)

    if comment_box is None:
        print("No comment textbox found on the post page.")
        return

    # Fill the comment
    await comment_box.fill(COMMENT_TEXT)

    # 6) Find and click submit button, preferring buttons inside the same form (full path)
    submit_clicked = False
    button_names = [
        "Post Comment",
        "Post",
        "Submit",
        "Submit Comment",
        "Add Comment",
        "Comment",
        "Send",
        "Publish",
        "Leave a comment",
    ]

    if await form_locator.count() > 0:
        form = form_locator.nth(0)
        for name in button_names:
            btn = form.get_by_role("button", name=name)
            if await btn.count() > 0:
                await btn.nth(0).click()
                submit_clicked = True
                break
        # Fallback to any button inside the form
        if not submit_clicked:
            form_buttons = form.get_by_role("button")
            if await form_buttons.count() > 0:
                await form_buttons.nth(0).click()
                submit_clicked = True

    # Page-level fallbacks
    if not submit_clicked:
        for name in button_names:
            btn = page.get_by_role("button", name=name)
            if await btn.count() > 0:
                await btn.nth(0).click()
                submit_clicked = True
                break

    if not submit_clicked:
        all_buttons = page.get_by_role("button")
        if await all_buttons.count() > 0:
            await all_buttons.nth(0).click()
            submit_clicked = True

    if not submit_clicked:
        print("Could not find a submit control to post the comment.")
    else:
        # Comment submit attempted; clicking may have navigated away which is expected
        return

